import itertools, sys

def is_nae_satisfied(clauses, assign):
    # assign dict var->bool
    for clause in clauses:
        vals = []
        for lit in clause:
            var = abs(lit)
            val = assign[var]
            if lit < 0:
                val = not val
            vals.append(val)
        # NAE: not all equal
        if all(vals) or not any(vals):
            return False
    return True

