for r in range(1,5):
    for subset in itertools.combinations(clauses, r):
        # check if unsat
        sat = False
        for assign_vals in itertools.product([False,True], repeat=4): # vars up to 3, but include index 0 unused
            assign = {i+1: assign_vals[i] for i in range(3)}
            if is_nae_satisfied(subset, assign):
                sat = True
                break
        if not sat:
            print('found unsat', r, subset)
